    "name": "Salep ZUDAIFU Original 100% mengatasi Eksim Jamur Kurap Alergi Kudis dll",
    "description": "<p>isi 15 gram, berat berikut kemasan (free bubble wrap) 35 gram<br>expired date panjang krna brng selalu barang terbaru dr pabrik<br><br>Salep herbal Cina ini dapat digunakan untuk mengobati Psoriasis, Eksim, Jerawat, Keratosis Pilaris (KP), Rosacea, ruam dan berbagai masalah kulit lainnya. Zudaifu juga disinfektan untuk infeksi jamur seperti psoriasis, Capitis, tinea, kudis, kurap, tinea, dan beri-beri.<br><br>Untuk menggunakan: Oleskan lapisan tipis pada area yang terkena dan pijat perlahan sampai benar-benar terserap. Ulangi dua kali sehari.<br><br>Bahan: Sophorae Flavesgentis radix (ramuan obat anti-inflamasi Cina), Stermonae radix (ramuan obat anti-bakteri dan antijamur Cina), Cnidii Fructus (ramuan obat Cina yang membunuh parasit), Kochiae Fructus (ramuan obat Cina yang digunakan untuk membersihkan panas dan menghilangkan kelembaban) , Menthae Haplocalycis herba (ramuan obat Cina untuk ruam), Ekstrak, Chlorhexidine acetate (pembersih kulit untuk luka), Asam Stearic, Sulfat Monostearat, Glycerol Vineargear, Petrolatum, Air Murni.<br>Catatan untuk Ibu menyusui: produk ini dapat menyebabkan penurunan pasokan susu. Tidak direkomendasikan untuk digunakan selama kehamilan<br><br>PERINGATAN : Hindari mata dan area di sekitar mata. The Menthae Haplocalycis adalah mint dan akan menyebabkan sensasi terbakar di mata<br><br>Untuk usia 6th keatas</p>",
